-- Hints only, and only where the domain is nobody's row yet: this file can
-- never take a domain away from whoever holds it.
insert into public.company_domains
  (company_id, domain, domain_type, evidence_confidence, source)
select c.id, d.domain, d.domain_type, d.evidence_confidence, d.source
from _company_directory_v2 as d
join public.companies as c on c.slug = d.slug
where not exists (select 1 from public.company_domains as e where e.domain = d.domain)
on conflict (company_id, domain) do nothing;

-- The observations behind the claims. Deleting and re-inserting one domain's
-- evidence is how a re-check refreshes it, so the key is the observation.
insert into public.domain_evidence (company_id, domain, evidence_type, source_url, checked)
select c.id, e.domain, e.evidence_type, e.source_url, e.checked
from _company_evidence_v2 as e
join public.companies as c on c.slug = e.slug
on conflict (company_id, domain, evidence_type, source_url) do nothing;

drop table if exists _company_directory_v2, _company_evidence_v2;

end
